import java.util.*;
import java.io.*;

public class Main {
    static final int MOD = 1000000007;

    static long fastExp(long base, int exp) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine());
        int[][] prob = new int[n][n];

        long inv100 = fastExp(100, MOD - 2);
        for (int i = 0; i < n; i++) {
            String[] parts = br.readLine().split(" ");
            for (int j = 0; j < n; j++) {
                int val = Integer.parseInt(parts[j]);
                prob[i][j] = (int)((long)val * inv100 % MOD);
            }
        }

        List<List<Integer>> groupSizes = new ArrayList<>();
        List<List<Integer>> allSubsets = new ArrayList<>();
        for (int size = 0; size <= n; size++) {
            groupSizes.add(new ArrayList<>());
            allSubsets.add(new ArrayList<>());
        }

        for (int size = 0; size <= n; size++) {
            for (int s = 0; s < (1 << n); s++) {
                if (Integer.bitCount(s) == size) {
                    groupSizes.get(size).add(s);
                    allSubsets.get(size).add(s);
                }
            }
        }

        List<Map<Long, Long>> dpStates = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            dpStates.add(new HashMap<>());
        }
        dpStates.get(0).put(1L, 1L);

        for (int i = 1; i <= n; i++) {
            Map<Long, Long> prevDP = dpStates.get(i - 1);
            Map<Long, Long> currDP = dpStates.get(i);
            List<Integer> allSubsetsI = allSubsets.get(i);
            List<Integer> groupSizesI = groupSizes.get(i);
            for (int s = 0; s < (1 << n); s++) {
                long prod = 1;
                for (int j = 0; j < n; j++) {
                    if (((s >> j) & 1) == 1) {
                        prod = (prod * prob[i - 1][j]) % MOD;
                    } else {
                        prod = (prod * (1 + MOD - prob[i - 1][j])) % MOD;
                    }
                }
                for (Map.Entry<Long, Long> entry : prevDP.entrySet()) {
                    long f = entry.getKey();
                    long count = entry.getValue();
                    long mask = 0;
                    for (int t : allSubsetsI) {
                        for (int j = 0; j < n; j++) {
                            if (((t >> j) & 1) == 1 && ((s >> j) & 1) == 1) {
                                int sizeOfGroup = groupSizesI.get(Integer.numberOfTrailingZeros(t));
                                if (((f >> sizeOfGroup) & 1) == 1) {
                                    mask |= 1L << sizeOfGroup;
                                    break;
                                }
                            }
                        }
                    }
                    long newVal = (currDP.getOrDefault(mask, 0L) + count * prod) % MOD;
                    currDP.put(mask, newVal);
                }
            }
        }

        System.out.println(dpStates.get(n).getOrDefault(1L, 0L));
    }
}
